"""
CropXAI Evidence Registry
===========================

Stores explicit artifacts (figures, tables) and statistics that 
support a specific scientific claim or hypothesis.
"""

from __future__ import annotations

import logging
from typing import Any

logger = logging.getLogger(__name__)


class EvidenceRegistry:
    """Registers hard evidence generated by experiments."""

    def __init__(self) -> None:
        self.evidence: dict[str, dict[str, Any]] = {}

    def register_evidence(
        self,
        evidence_id: str,
        experiment_ids: list[str],
        figures: list[str],
        tables: list[str],
        p_value: float,
        effect_size: float
    ) -> None:
        """Registers a block of evidence."""
        self.evidence[evidence_id] = {
            "experiments": experiment_ids,
            "figures": figures,
            "tables": tables,
            "p_value": p_value,
            "effect_size": effect_size
        }
        logger.info("Registered Evidence [%s] supported by %d experiments.", evidence_id, len(experiment_ids))

    def get_evidence(self, evidence_id: str) -> dict[str, Any] | None:
        return self.evidence.get(evidence_id)


__all__ = ["EvidenceRegistry"]
